diff --git a/evaluation/attribution/collect-artifacts.test.mjs b/evaluation/attribution/collect-artifacts.test.mjs
new file mode 100644
index 0000000..b188a3c
--- /dev/null
+++ b/evaluation/attribution/collect-artifacts.test.mjs
@@ -0,0 +1,57 @@
+/**
+ * Regression: the exit status of a real CodeBuddy tool result must be read.
+ *
+ * Real results spell the line `Exit Code:` (capital C). The reader used to
+ * match only `Exit code:`, so every real result came back with `exit_code:
+ * null` and anything downstream that classifies a call by its exit status
+ * (a curl that timed out with stderr suppressed has nothing else to show)
+ * silently lost its signal.
+ *
+ * The label is taken case-insensitively, so both spellings read the same and
+ * nothing else about the outcome changes.
+ */
+
+import { test } from "node:test";
+import assert from "node:assert/strict";
+
+import { outcomeOf, collectArtifacts } from "./collect-artifacts.mjs";
+
+// Shaped like a real result envelope: the three labelled sections and the
+// capital-C label.
+const envelope = (exit, label = "Exit Code") =>
+  `Command: curl -s http://127.0.0.1:8096/skill-bridge/v3/skill/get\n`
+  + `Stdout: \nStderr: \n${label}: ${exit}\nSignal: (none)`;
+
+test("a real result's capital `Exit Code:` yields the exit status, not null", () => {
+  assert.equal(outcomeOf(envelope(28)).exit_code, 28);
+  assert.equal(outcomeOf(envelope(52)).exit_code, 52);
+  assert.equal(outcomeOf(envelope(0)).exit_code, 0);
+});
+
+test("the lower-case `Exit code:` spelling reads the same", () => {
+  assert.equal(outcomeOf(envelope(7, "Exit code")).exit_code, 7);
+});
+
+test("a result with no exit line stays null", () => {
+  assert.equal(outcomeOf("Command: echo hi\nStdout: hi").exit_code, null);
+});
+
+test("collectArtifacts carries the exit status onto the operation", () => {
+  const captureEvents = [{
+    event: "http.request",
+    requestId: "req-1",
+    timestamp: "2026-09-04T13:30:00Z",
+    headers: { "x-conversation-id": "conv-1" },
+    body: {
+      json: {
+        messages: [
+          { role: "assistant", tool_calls: [{ id: "c1", function: { name: "Bash", arguments: "{}" } }] },
+          { role: "tool", tool_call_id: "c1", content: envelope(28) },
+        ],
+      },
+    },
+  }];
+
+  const [session] = collectArtifacts({ captureEvents });
+  assert.equal(session.operations[0].result.exit_code, 28);
+});

delivered_content.text:
  1→/**
  2→ * Artifact collection — the places where a discriminative token could land.
  3→ *
  4→ * A token found "somewhere in the run" cannot support a `used` claim. What is
  5→ * needed is a specific operation: this tool call, at this point in the session,
  6→ * with this result. So everything collected here carries three things:
  7→ *
  8→ *   message_index  where it sits in the session's message sequence. This is what
  9→ *                  ordering is judged on, and it is not the same as time: a
 10→ *                  model can emit several tool calls in one message, so two
 11→ *                  calls share a timestamp while the second was written before
 12→ *                  the first one's result existed. Using the timestamp there
 13→ *                  reads "the content arrived at 10:01 and the call is stamped
 14→ *                  10:01" as influence, when the model had not seen a thing.
 15→ *   seq            position among this session's calls, for display.
 16→ *   call_id      which result belongs to which call. A command and its output
 17→ *                must stay attached: the command carries what was asked for and
 18→ *                the output carries what came back, and the two answer different
 19→ *                questions.
 20→ *   locus        where to look to see it again — request id, message index,
 21→ *                call id, or file and hunk. An event whose evidence cannot be
 22→ *                reopened is an assertion, not a record.
 23→ *
 24→ * `occurred_at` is the timestamp of the earliest captured request that carried
 25→ * the message. Messages accumulate across turns, so the last request holds them
 26→ * all; the first one to contain a message is when it happened.
 27→ *
 28→ * A diff hunk has no position at all. A diff is the end state of a run, not an
 29→ * event within it, so it gets `message_index: null` and `ordering:
 30→ * "end_of_run"` — and "after everything" is *not* good enough to establish that
 31→ * an asset was read first. A run that edits a file and then reads the asset
 32→ * leaves the same diff as one that reads first and then edits. The judge
 33→ * therefore refuses to promote on a diff hunk alone; the edit operation that
 34→ * produced the change is what carries a position, and that is what gets judged.
 35→ *
 36→ * Usage:
 37→ *   node evaluation/attribution/collect-artifacts.mjs <capture.jsonl ...> \
 38→ *     [--task=<task.md>] [--diff=<file.diff>] [--pre=<path>=<file> ...] [--json]
 39→ */
 40→
 41→import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
 42→import { dirname } from "node:path";
 43→import {
 44→  normalizeSessionKey,
 45→  parseJsonl,
 46→  splitCommandAndOutput,
 47→  commandEndpoint,
 48→  isListingAction,
 49→} from "../provenance/build-events.mjs";
 50→
 51→/** Commands that run a check rather than change something. */
 52→const TEST_COMMAND = /\b(npm|pnpm|yarn)\s+(run\s+)?test\b|\bnode\s+--test\b|\bpytest\b|\bgo\s+test\b|\bcargo\s+test\b|\bvitest\b|\bjest\b|verify[\w-]*\.sh\b/;
 53→
 54→function textOf(content) {
 55→  return typeof content === "string" ? content : JSON.stringify(content ?? "");
 56→}
 57→
 58→/** Tool results in one captured request, each with the message index it sat at. */
 59→function toolResults(body) {
 60→  const out = [];
 61→  const msgs = Array.isArray(body?.messages) ? body.messages : [];
 62→  msgs.forEach((message, index) => {
 63→    if (message?.role === "tool") out.push({ index, text: textOf(message.content) });
 64→    for (const block of Array.isArray(message?.content) ? message.content : []) {
 65→      if (block?.type === "tool_result") out.push({ index, text: textOf(block.content) });
 66→    }
 67→  });
 68→  return out;
 69→}
 70→
 71→/**
 72→ * Walk one captured request's messages, emitting a record per tool call and per
 73→ * tool result, in message order.
 74→ */
 75→function messagesOf(body) {
 76→  const out = [];
 77→  const msgs = Array.isArray(body?.messages) ? body.messages : [];
 78→  msgs.forEach((message, index) => {
 79→    if (Array.isArray(message?.tool_calls)) {
 80→      for (const tc of message.tool_calls) {
 81→        out.push({
 82→          index,
 83→          role: "call",
 84→          call_id: String(tc?.id ?? ""),
 85→          tool_name: String(tc?.function?.name ?? tc?.name ?? ""),
 86→          text: String(tc?.function?.arguments ?? JSON.stringify(tc?.input ?? "")),
 87→        });
 88→      }
 89→    }
 90→    // Anthropic-shaped blocks carry tool_use / tool_result inside content.
 91→    const blocks = Array.isArray(message?.content) ? message.content : [];
 92→    for (const block of blocks) {
 93→      if (block?.type === "tool_use") {
 94→        out.push({
 95→          index, role: "call",
 96→          call_id: String(block.id ?? ""),
 97→          tool_name: String(block.name ?? ""),
 98→          text: JSON.stringify(block.input ?? ""),
 99→        });
100→      } else if (block?.type === "tool_result") {
101→        out.push({
102→          index, role: "result",
103→          call_id: String(block.tool_use_id ?? ""),
104→          tool_name: "",
105→          text: textOf(block.content),
106→        });
107→      }
108→    }
109→    if (message?.role === "tool") {
110→      out.push({
111→        index, role: "result",
112→        call_id: String(message.tool_call_id ?? ""),
113→        tool_name: "",
114→        text: textOf(message.content),
115→      });
116→    }
117→  });
118→  return out;
119→}
120→
121→/** Exit status and stderr, read out of a shell tool result envelope. */
122→export function outcomeOf(resultText) {
123→  const s = String(resultText ?? "");
124→  const code = /(?:^|\n)Exit code:\s*(\d+)/.exec(s);
125→  const stderr = /(?:^|\n)Stderr:\s*([\s\S]*)$/.exec(s);
126→  return {
127→    exit_code: code ? Number(code[1]) : null,
128→    stderr: stderr ? stderr[1].trim().slice(0, 400) : "",
129→  };
130→}
131→
132→/**
133→ * Split a unified diff into hunks, each keeping the file and line range it
134→ * touches — "the token is in the diff" is not a location, "the token is in
135→ * src/proxy.ts lines 40-58" is.
136→ */
137→export function diffHunks(diffText) {
138→  const hunks = [];
139→  let file = "";
140→  let current = null;
141→  for (const line of String(diffText ?? "").split("\n")) {
142→    const plus = /^\+\+\+ [ab]\/(.+)$/.exec(line);
143→    if (plus) { file = plus[1]; current = null; continue; }
144→    const at = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/.exec(line);
145→    if (at) {
146→      current = {
147→        file,
148→        start: Number(at[1]),
149→        end: Number(at[1]) + (at[2] ? Number(at[2]) : 1) - 1,
150→        lines: [],
151→      };
152→      hunks.push(current);
153→      continue;
154→    }
155→    if (current && /^[+ -]/.test(line)) current.lines.push(line);
156→  }
157→  return hunks.map((h) => ({ ...h, text: h.lines.join("\n") }));
158→}
159→
160→/**
161→ * Collect every operation in a run, ordered, with calls and results paired.
162→ *
163→ * Messages repeat across turns as the conversation grows. A call is recorded
164→ * once, at the turn it first appeared, so the sequence reflects when things
165→ * happened rather than how many times they were re-sent.
166→ */
167→export function collectArtifacts({ captureEvents = [], taskDescription = "", preChangeFiles = {}, diff = "", runId = null, taskId = null }) {
168→  const bySession = new Map();
169→
170→  const requests = captureEvents
171→    .filter((e) => e?.event === "http.request" && Array.isArray(e?.body?.json?.messages))
172→    .sort((a, b) => String(a.timestamp ?? "").localeCompare(String(b.timestamp ?? "")));
173→
174→  for (const event of requests) {
175→    const sessionKey = normalizeSessionKey(
176→      event?.headers?.["x-conversation-id"] ?? event?.headers?.["X-Conversation-Id"] ?? "",
177→    );
178→    if (!bySession.has(sessionKey)) bySession.set(sessionKey, { calls: new Map(), results: new Map() });
179→    const store = bySession.get(sessionKey);
180→    const requestId = String(event.requestId ?? "");
181→    const timestamp = String(event.timestamp ?? "");
182→
183→    for (const m of messagesOf(event.body.json)) {
184→      // Key on the call id where there is one. Without it a message can still
185→      // be identified by where it sits, which is stable across turns because
186→      // messages are only ever appended.
187→      const key = m.call_id || `${m.role}@${m.index}`;
188→      const target = m.role === "call" ? store.calls : store.results;
189→      if (target.has(key)) continue; // already seen in an earlier turn
190→      target.set(key, {
191→        ...m,
192→        first_seen_at: timestamp,
193→        locus: `request(${requestId}):msg[${m.index}]${m.call_id ? `:${m.call_id}` : ""}`,
194→      });
195→    }
196→  }
197→
198→  // What the model was *offered* without fetching: the body of every search /
199→  // list result. A discriminative token that appears in one of these reached
200→  // the model as a snippet, not through a full-content read — so a later use of
201→  // it cannot be told apart from having read the snippet. Kept with the message
202→  // index it arrived at, so the judge can screen only what preceded an
203→  // operation. Confirmed necessary by the real run: `47318` came back in 13
204→  // search snippets while `10.244.7.19` came back in none.
205→  // Every tool result's output, not only search results. The first real run
206→  // showed why the narrower version is not enough: the consumer's own
207→  // auto-extracted skill was read at message 4, before any of the credited
208→  // assets. It happened not to carry the discriminative tokens that time —
209→  // but a token delivered by *any* earlier result (another asset's body, a
210→  // file read, a search snippet) means its later use cannot be credited to
211→  // the fetch the judge is looking at. So the judge is given everything that
212→  // arrived, with where it came from, and decides by earliest delivery.
213→  const deliveredBySession = new Map();
214→  for (const event of requests) {
215→    const sessionKey = normalizeSessionKey(
216→      event?.headers?.["x-conversation-id"] ?? event?.headers?.["X-Conversation-Id"] ?? "",
217→    );
218→    for (const { index, text } of toolResults(event.body.json)) {
219→      const { command, output } = splitCommandAndOutput(text);
220→      if (!output) continue;
221→      const endpoint = commandEndpoint(command);
222→      if (!deliveredBySession.has(sessionKey)) deliveredBySession.set(sessionKey, new Map());
223→      const byIndex = deliveredBySession.get(sessionKey);
224→      // First arrival of a given result is when it was delivered.
225→      if (!byIndex.has(index)) {
226→        byIndex.set(index, {
227→          message_index: index,
228→          endpoint: endpoint || null,
229→          kind: endpoint ? (isListingAction(endpoint) ? "listing" : "fetch") : "other",
230→          // Enough of the command to name the source in a judgement; not the
231→          // full text, which can be long and carries nothing the locus lacks.
232→          source: String(command ?? "").trim().split("\n")[0].slice(0, 160),
233→          text: output,
234→        });
235→      }
236→    }
237→  }
238→  const offeredBySession = new Map();
239→  for (const [sessionKey, byIndex] of deliveredBySession) {
240→    const listings = new Map();
241→    for (const [i, d] of byIndex) if (d.kind === "listing") listings.set(i, d);
242→    offeredBySession.set(sessionKey, listings);
243→  }
244→
245→  const sessions = [];
246→  for (const [sessionKey, store] of bySession) {
247→    const operations = [];
248→    const ordered = [...store.calls.values()].sort((a, b) => a.index - b.index);
249→
250→    ordered.forEach((call, seq) => {
251→      const result = store.results.get(call.call_id) ?? null;
252→      const { command, output } = splitCommandAndOutput(result?.text ?? "");
253→      operations.push({
254→        seq,
255→        kind: TEST_COMMAND.test(call.text) ? "test_command" : "tool_call",
256→        // The position the model wrote this call at. Ordering is judged on it,
257→        // never on the timestamp — see the note at the top of this file.
258→        message_index: call.index,
259→        occurred_at: call.first_seen_at || null,
260→        ordering: "observed",
261→        call_id: call.call_id,
262→        tool_name: call.tool_name,
263→        locus: `${call.locus}:arguments`,
264→        // The arguments are where a token the model *acted on* appears — in the
265→        // mainline scenario the bridge address is inside the curl command here,
266→        // not in anything that came back.
267→        text: call.text,
268→        result: result
269→          ? {
270→              message_index: result.index,
271→              locus: result.locus,
272→              // Kept apart deliberately: the echoed command says what was asked
273→              // for and the output says what came back. Scanning them as one
274→              // blob is how a call that timed out with empty output still
275→              // matched every pattern in its own command.
276→              command_echo: command,
277→              output,
278→              ...outcomeOf(result.text),
279→            }
280→          : null,
281→      });
282→    });
283→
284→    // A diff has no time of its own; it is what the run left behind.
285→    diffHunks(diff).forEach((h, i) => {
286→      operations.push({
287→        seq: operations.length + i,
288→        kind: "diff_hunk",
289→        // No position and no time. "After everything" cannot show the asset was
290→        // read before the edit, because a run that edited first and read after
291→        // leaves exactly this diff.
292→        message_index: null,
293→        occurred_at: null,
294→        ordering: "end_of_run",
295→        call_id: "",
296→        tool_name: "",
297→        locus: `diff:${h.file}:${h.start}-${h.end}`,
298→        text: h.text,
299→        result: null,
300→      });
301→    });
302→
303→    sessions.push({
304→      session_key: sessionKey,
305→      // Stamped by the runner so the judge's events carry them; null when the
306→      // artifacts were collected outside a run. Generalisation is counted as
307→      // distinct task ids, so a missing task id is a missing signal, not zero.
308→      run_id: runId,
309→      task_id: taskId,
310→      task_description: taskDescription,
311→      pre_change_files: preChangeFiles,
312→      diff,
313→      offered_content: [...(offeredBySession.get(sessionKey)?.values() ?? [])]
314→        .sort((a, b) => a.message_index - b.message_index),
315→      // Everything that came back from any tool, in arrival order. The judge
316→      // credits a token to a fetch only when that fetch is the token's
317→      // earliest delivery; anything earlier — another asset's body, a file
318→      // read, a snippet — means the credit cannot be given.
319→      delivered_content: [...(deliveredBySession.get(sessionKey)?.values() ?? [])]
320→        .sort((a, b) => a.message_index - b.message_index),
321→      operations,
322→      test_commands: operations.filter((o) => o.kind === "test_command").map((o) => o.locus),
323→      tool_call_args: operations.filter((o) => o.kind !== "diff_hunk").map((o) => o.text),
324→    });
325→  }
326→  return sessions;
327→}
328→
329→export function renderArtifacts(sessions) {
330→  const lines = ["# Collected artifacts", ""];
331→  if (sessions.length === 0) {
332→    lines.push("No session in the capture carried a tool call. Nothing to attribute against —");
333→    lines.push("**not** an empty result meaning nothing was used.");
334→    return lines.join("\n");
335→  }
336→  for (const s of sessions) {
337→    lines.push(`## ${s.session_key || "(no conversation id)"}`, "");
338→    lines.push(`  ${s.operations.length} operation(s), ${s.test_commands.length} of them checks`);
339→    lines.push(`  task description: ${s.task_description ? `${s.task_description.length} chars` : "not supplied"}`);
340→    lines.push(`  pre-change files: ${Object.keys(s.pre_change_files).length}`);
341→    lines.push("");
342→    for (const op of s.operations.slice(0, 25)) {
343→      const when = op.message_index == null ? op.ordering : `msg[${op.message_index}]`;
344→      const outcome = op.result
345→        ? (op.result.exit_code === null ? "" : ` exit=${op.result.exit_code}`)
346→        : " (no result)";
347→      lines.push(`  [${String(op.seq).padStart(2)}] ${op.kind.padEnd(12)} ${when}  ${op.tool_name || "-"}${outcome}`);
348→      lines.push(`       ${op.locus}`);
349→    }
350→    if (s.operations.length > 25) lines.push(`  … ${s.operations.length - 25} more`);
351→    lines.push("");
352→  }
353→  return lines.join("\n");
354→}
355→
356→// ── CLI ───────────────────────────────────────────────────────────
357→if (import.meta.url === `file://${process.argv[1]}`) {
358→  const args = process.argv.slice(2);
359→  const flag = (n) => args.filter((a) => a.startsWith(`--${n}=`)).map((a) => a.slice(n.length + 3));
360→  const capturePaths = args.filter((a) => !a.startsWith("--"));
361→  if (capturePaths.length === 0) {
362→    console.error("usage: node collect-artifacts.mjs <capture.jsonl ...> [--task=f] [--diff=f] [--pre=path=file] [--json]");
363→    process.exit(2);
364→  }
365→
366→  const preChangeFiles = {};
367→  for (const spec of flag("pre")) {
368→    const at = spec.indexOf("=");
369→    if (at < 0) { console.error(`--pre expects <path>=<file>, got ${spec}`); process.exit(2); }
370→    preChangeFiles[spec.slice(0, at)] = readFileSync(spec.slice(at + 1), "utf8");
371→  }
372→
373→  const sessions = collectArtifacts({
374→    captureEvents: capturePaths.flatMap((p) => parseJsonl(readFileSync(p, "utf8"))),
375→    taskDescription: flag("task").map((p) => readFileSync(p, "utf8")).join("\n"),
376→    diff: flag("diff").map((p) => readFileSync(p, "utf8")).join("\n"),
377→    preChangeFiles,
378→    runId: flag("run-id")[0] || null,
379→    taskId: flag("task-id")[0] || null,
380→  });
381→
382→  const outPath = "evaluation/attribution/artifacts/run-artifacts.json";
383→  mkdirSync(dirname(outPath), { recursive: true });
384→  writeFileSync(outPath, JSON.stringify(sessions, null, 2), "utf8");
385→
386→  if (args.includes("--json")) console.log(JSON.stringify(sessions, null, 2));
387→  else console.log(renderArtifacts(sessions), `\nWritten to ${outPath}`);
388→}
