 1→/**
 2→ * Which row a run lands in.
 3→ *
 4→ * The formal sample is the manifest (`batch4-runs.json`), not "every run whose
 5→ * baseline says batch 4": the trial pair and the preparation runs carry the
 6→ * same baseline and were being counted into the batch-4 row (28 decisions
 7→ * instead of 20). The manifest decides membership; labels only name the
 8→ * non-sample rows.
 9→ */
10→
11→import { test } from "node:test";
12→import assert from "node:assert/strict";
13→
14→import { experimentOf } from "./calibrate-runs.mjs";
15→
16→const manifest = { batch: 4, runs: [{ run_id: "f1" }, { run_id: "f2" }] };
17→
18→test("a run named in the manifest is the formal sample, whatever its label", () => {
19→  assert.equal(experimentOf({ label: "gate-off", run_id: "f1", base: "batch4", manifest }), "batch4");
20→  assert.equal(experimentOf({ label: "gate-on", run_id: "f2", base: "batch4", manifest }), "batch4");
21→});
22→
23→test("the trial pair is its own row, not a sample", () => {
24→  assert.equal(experimentOf({ label: "trial-gate-off", run_id: "t1", base: "batch4", manifest }), "batch4-trial (checkpoint pair, not a sample)");
25→  assert.equal(experimentOf({ label: "trial-gate-on", run_id: "t2", base: "batch4", manifest: null }), "batch4-trial (checkpoint pair, not a sample)");
26→});
27→
28→test("preparation runs stay the evidence-base row", () => {
29→  assert.equal(experimentOf({ label: "b4-prep", run_id: "p1", base: "batch4", manifest }), "batch4-prep (evidence base, not a sample)");
30→});
31→
32→test("a batch-4 run that is neither in the manifest nor labelled prep/trial is listed apart, never folded into the sample", () => {
33→  assert.equal(experimentOf({ label: "gate-off", run_id: "stray", base: "batch4", manifest }), "batch4-other (not in the formal manifest)");
34→});
